// Fetch all records of a CRM module (paginated), requesting a specific field set.
async function fetchAllCrmModule(crmToken, module, fields) {
  const out = [];
  for (let page = 1; page <= 50; page++) {
    const r = await axios.get(`https://www.zohoapis.com/crm/v2/${module}`, {
      params: { fields: fields.join(','), per_page: 200, page },
      headers: { Authorization: `Zoho-oauthtoken ${crmToken}` }, validateStatus: () => true, timeout: 25000,
    });
    if (r.status === 204) break;
    if (r.status !== 200) throw new Error(`${module} HTTP ${r.status}: ${JSON.stringify(r.data).slice(0, 200)}`);
    out.push(...(r.data?.data || []));
    if (!r.data?.info?.more_records) break;
  }
  return out;
}

// SH-14 end-to-end coverage diagnostic: how many Zentact merchants link to a SaaS subscription
// via Project_Cases.Adyen_Store_ID → account → Subscription_Number → Zoho Billing.
// GET /api/admin/sh14-coverage?secret=
app.get('/api/admin/sh14-coverage', requireOpsSecret, async (req, res) => {
  const norm = (s) => String(s || '').trim().toLowerCase();
  const lookupName = (v) => (v && (v.name || v)) || '';
  try {
    const crmToken = await ensureValidCrmToken();
    if (!crmToken) return res.status(400).json({ error: 'CRM not connected' });
    // 1) Project_Cases → storeId→account map, and account→subscription_numbers
    const cases = await fetchAllCrmModule(crmToken, 'Project_Cases', ['Adyen_Store_ID', 'Subscription_Number', 'Account_Name', 'Deal_Name', 'Restaurant_Name', 'Type']);
    const caseByStore = new Map();      // adyen storeId → account name
    const subsByAccount = new Map();    // normalized account → Set(subscription_number)
    const subsByRestaurant = new Map(); // normalized restaurant name → Set(subscription_number)
    const addTo = (map, key, val) => { if (key) { if (!map.has(key)) map.set(key, new Set()); map.get(key).add(val); } };
    let casesWithStore = 0, casesWithSub = 0;
    for (const c of cases) {
      const sid = String(c.Adyen_Store_ID || '').trim();
      const acc = lookupName(c.Account_Name);
      const rest = lookupName(c.Restaurant_Name);
      if (sid) { casesWithStore++; caseByStore.set(sid, acc); }
      const sub = String(c.Subscription_Number || '').trim();
      if (sub) { casesWithSub++; addTo(subsByAccount, norm(acc), sub); addTo(subsByRestaurant, norm(rest), sub); }
    }
    // 2) Billing active subs → subscription_number → monthly MRR
    const { accessToken, apiDomain } = await getAdminBooksAuth();
    const subMrr = new Map();           // subscription_number → monthly MRR
    const subMrrByCustomer = new Map(); // normalized billing customer_name → monthly MRR
    for (const orgId of ZOHO_BILLING_ORG_IDS) {
      const all = await fetchBillingSubs(apiDomain, accessToken, orgId, 'SubscriptionStatus.All');
      for (const s of all) {
        if (!ACTIVE_STATUSES.has(String(s.status || '').toLowerCase())) continue;
        const mm = subMonthlyAmount(s.sub_total != null ? s.sub_total : s.amount, s.interval, s.interval_unit);
        const num = String(s.subscription_number || '').trim();
        if (num) subMrr.set(num, (subMrr.get(num) || 0) + mm);
        const cust = norm(s.customer_name);
        if (cust) subMrrByCustomer.set(cust, (subMrrByCustomer.get(cust) || 0) + mm);
      }
    }
    // 3) Zentact merchants → walk the chain
    const merchants = (await pool.query(`SELECT merchant_account_id, business_name, stores FROM zentact_merchants`)).rows;
    const resolveMrr = (subs) => { let mrr = 0, hit = false; for (const sn of subs) if (subMrr.has(sn)) { hit = true; mrr += subMrr.get(sn); } return hit ? mrr : null; };
    let withStore = 0, storeMatched = 0;
    let viaStoreId = 0, viaCaseName = 0, viaDirectName = 0, resolvedAny = 0, matchedMrr = 0;
    const sampleUnresolved = [];
    for (const m of merchants) {
      let stores = []; try { stores = Array.isArray(m.stores) ? m.stores : JSON.parse(m.stores || '[]'); } catch { /* */ }
      const storeIds = stores.map(s => String(s.storeId || '').trim()).filter(Boolean);
      if (storeIds.length) withStore++;
      // Path A — precise: storeId → case (Adyen_Store_ID) → account → its subscription numbers.
      const acc = storeIds.map(id => caseByStore.get(id)).find(Boolean);
      if (acc) storeMatched++;
      let mrr = acc ? resolveMrr(subsByAccount.get(norm(acc)) || new Set()) : null;
      if (mrr != null) viaStoreId++;
      // Path B — merchant name → CRM case (Restaurant_Name) → its subscription numbers.
      if (mrr == null) {
        const m2 = resolveMrr(subsByRestaurant.get(norm(m.business_name)) || new Set());
        if (m2 != null) { mrr = m2; viaCaseName++; }
      }
      // Path C — direct: merchant name → Zoho Billing customer_name (no CRM in between).
      if (mrr == null) {
        const m3 = subMrrByCustomer.get(norm(m.business_name));
        if (m3 != null && m3 > 0) { mrr = m3; viaDirectName++; }
      }
      if (mrr != null) { resolvedAny++; matchedMrr += mrr; }
      else if (sampleUnresolved.length < 10) sampleUnresolved.push({ name: m.business_name, stores: storeIds.length });
    }
    res.json({
      projectCases: { total: cases.length, withAdyenStoreId: casesWithStore, withSubscriptionNumber: casesWithSub },
      billing: { activeSubsWithNumber: subMrr.size, distinctCustomerNames: subMrrByCustomer.size },
      zentact: { totalMerchants: merchants.length, withStoreId: withStore, storeMatchedToCase: storeMatched },
      resolved: { viaStoreId, viaCaseName, viaDirectName, totalMerchantsWithSaaS: resolvedAny, pctOfMerchants: Math.round(resolvedAny / merchants.length * 1000) / 10, matchedSaasMrr: Math.round(matchedMrr * 100) / 100 },
      sampleUnresolved,
    });
  } catch (e) { res.status(502).json({ error: e.message }); }
});

// GET /api/admin/find-salesperson?secret=&q= — search the salespeople table AND recent Zoho
// Books estimates for a salesperson name (to locate a rep who only has estimates, no invoices).
app.get('/api/admin/find-salesperson', requireOpsSecret, async (req, res) => {
  const q = String(req.query.q || '').trim();
  if (!q) return res.status(400).json({ error: 'q required' });
  try {
    const sp = (await pool.query(`SELECT name, is_active FROM salespeople WHERE name ILIKE '%' || $1 || '%' ORDER BY name`, [q])).rows;
    const { accessToken, apiDomain } = await getAdminBooksAuth();
    const counts = {};
    let scanned = 0;
    for (let page = 1; page <= 12; page++) {
      const r = await axios.get(`${apiDomain}/books/v3/estimates`, {
        params: { organization_id: process.env.ZOHO_ORG_ID, per_page: 200, page, sort_column: 'date', sort_order: 'D' },
        headers: { Authorization: `Zoho-oauthtoken ${accessToken}` }, validateStatus: () => true, timeout: 25000,
      });
      if (r.status !== 200) break;
      const ests = r.data.estimates || [];
      scanned += ests.length;
      for (const e of ests) {
        const name = e.salesperson_name || '';
        if (name && name.toLowerCase().includes(q.toLowerCase())) {
          const k = `${name}|${e.status}`;
          counts[k] = (counts[k] || 0) + 1;
        }
      }
      if (!r.data.page_context?.has_more_page) break;
    }
    res.json({ q, salespeopleTable: sp, estimatesScanned: scanned, estimateMatches: counts });
  } catch (e) { res.status(502).json({ error: e.message }); }
});

// GET /api/admin/zentact-raw?secret=  — dump the FULL raw merchant object from the Zentact API
// (top-level fields, not just custom attributes) to find an Adyen/PSP identifier.
app.get('/api/admin/zentact-raw', requireOpsSecret, async (req, res) => {
  try {
    const zentact = new ZentactService(process.env.ZENTACT_API_KEY);
    const merchants = await zentact.getMerchantAccounts({ status: 'ACTIVE' });
    const allKeys = [...new Set(merchants.flatMap(m => Object.keys(m || {})))].sort();
    // Optional ?name= filter — inspect a specific merchant's stores[] structure.
    const q = String(req.query.name || '').trim().toLowerCase();
    if (q) {
      const matches = merchants
        .filter(m => String(m.businessName || '').toLowerCase().includes(q))
        .map(m => ({ businessName: m.businessName, merchantAccountId: m.merchantAccountId,
                     storeCount: Array.isArray(m.stores) ? m.stores.length : 0, stores: m.stores || [] }));
      return res.json({ count: merchants.length, query: q, matchCount: matches.length, matches });
    }
    res.json({ count: merchants.length, allKeys, sample: merchants.slice(0, 2) });
  } catch (e) { res.status(500).json({ error: e.message, detail: e.response?.data }); }
});

// GET /api/admin/zentact-store-raw?secret=&storeId=&merchantAccountId=  — probe Zentact's
// dedicated /stores endpoint to discover whether it returns a human "Store Name" (the
// merchant-accounts stores[] array only has storeId/storeReferenceId, no name).
app.get('/api/admin/zentact-store-raw', requireOpsSecret, async (req, res) => {
  const axios = require('axios');
  const base = process.env.ZENTACT_API_URL || 'https://api.zentact.com/api/v1';
  const headers = { 'X-API-Key': process.env.ZENTACT_API_KEY };
  const storeId = req.query.storeId;
  const mid = req.query.merchantAccountId;
  const tries = [
    ['GET /merchant-accounts/{mid}', `${base}/merchant-accounts/${mid}`, undefined],
    ['GET /merchant-accounts/{mid}/stores', `${base}/merchant-accounts/${mid}/stores`, undefined],
    ['GET /merchant-accounts?include=stores', `${base}/merchant-accounts`, { merchantAccountId: mid }],
  ];
  const out = {};
  for (const [label, url, params] of tries) {
    try {
      const r = await axios.get(url, { headers, params, validateStatus: () => true, timeout: 15000 });
      out[label] = { status: r.status, data: r.data };
    } catch (e) { out[label] = { error: e.message }; }
  }
  res.json(out);
});

