// GET /api/admin/saas-first-audit?secret=  — every saas_first invoice, flagged when the customer
// already had a MUCH older SaaS invoice (suspect: an old customer re-classified as a new
// activation because only their latest invoice got a subscription_activation_date).
app.get('/api/admin/saas-first-audit', requireOpsSecret, async (req, res) => {
  try {
    const rows = (await pool.query(`
      SELECT i.invoice_number, i.customer_name, i.salesperson_name,
             i.date::date AS date, i.commission::float AS commission,
             i.commission_payable_date::date AS payable_date, i.approval_status,
             i.subscription_activation_date::date AS activation_date,
             fs.first_saas_date,
             (i.date::date - fs.first_saas_date) > 45 AS had_prior_saas
        FROM invoices i
        JOIN LATERAL (
          SELECT MIN(e.date)::date AS first_saas_date
            FROM invoices e
           WHERE e.organization_id = i.organization_id AND e.customer_name = i.customer_name
             AND e.saas_amount > 0 AND e.status NOT IN ('void','deleted')
        ) fs ON true
       WHERE i.organization_id = $1 AND i.commission_status = 'saas_first'
       ORDER BY i.date DESC`, [process.env.ZOHO_ORG_ID])).rows;
    const flagged = rows.filter(r => r.had_prior_saas);
    res.json({
      total_saas_first: rows.length,
      flagged_count: flagged.length,
      flagged_commission: Math.round(flagged.reduce((s, r) => s + (r.commission || 0), 0) * 100) / 100,
      flagged,
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/first-month-fallback-preview?secret=  — read-only: which customers currently
// have NO initial-sale group at all (permanently stuck as renewals — the Yolks/Nicosia/Centre
// Eaton failure mode), among those with a recent (≤270d) monthly-SaaS invoice. Use this to check
// backfillActivationDates() progress (customers should drop off this list once their activation
// date resolves) and to flag anything that still needs a human review afterward.
app.get('/api/admin/first-month-fallback-preview', requireOpsSecret, async (req, res) => {
  try {
    const rows = (await pool.query(`
      WITH earliest_saas AS (
        SELECT customer_name, MIN(date) AS first_saas_date
          FROM invoices
         WHERE organization_id = $1 AND status NOT IN ('void','deleted') AND saas_amount > 0.005
         GROUP BY customer_name
      ),
      earliest_monthly AS (
        SELECT DISTINCT ON (i.customer_name) i.customer_name, i.id, i.invoice_number, i.date, i.saas_amount
          FROM invoices i
         WHERE i.organization_id = $1 AND i.status NOT IN ('void','deleted') AND i.saas_amount > 0.005
           AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(i.line_items) li
              WHERE li->>'type' = 'saas' AND li->>'name' ~* '(annual|annuel|yearly|par ann)'
           )
         ORDER BY i.customer_name, i.date ASC, i.id ASC
      ),
      has_group AS (
        SELECT DISTINCT i.customer_name
          FROM invoices i JOIN earliest_saas es ON es.customer_name = i.customer_name
         WHERE i.organization_id = $1 AND i.status NOT IN ('void','deleted')
           AND i.subscription_activation_date IS NOT NULL
           AND ABS(EXTRACT(EPOCH FROM (i.date - es.first_saas_date))) <= 45*86400
      ),
      tenure AS (
        SELECT customer_name, COUNT(*)::int AS total_invoices, MIN(date) AS earliest_invoice_any_type
          FROM invoices WHERE organization_id = $1 AND status NOT IN ('void','deleted')
         GROUP BY customer_name
      )
      SELECT em.customer_name, em.invoice_number, em.date::date AS date, em.saas_amount::float AS saas_amount,
             t.total_invoices, t.earliest_invoice_any_type::date AS earliest_invoice_any_type
        FROM earliest_monthly em
        JOIN tenure t ON t.customer_name = em.customer_name
       WHERE em.customer_name NOT IN (SELECT customer_name FROM has_group)
         AND em.date >= (CURRENT_DATE - INTERVAL '270 days')
       ORDER BY em.date`, [process.env.ZOHO_ORG_ID])).rows;
    res.json({ count: rows.length, total_saas_amount: Math.round(rows.reduce((s, r) => s + r.saas_amount, 0) * 100) / 100, rows });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/annual-slack-preview?secret=  — DRY RUN (no writes): which annual invoices are
// currently disqualified from the 10% first-year bonus (hadPriorSaas=true, no grace period) where
// the "prior" SaaS invoice is actually within 45 days beforehand — i.e. same onboarding week, not
// a genuinely pre-existing customer. Used to size the blast radius of adding the same slack this
// file already uses for the monthly-SaaS equivalent (INITIAL_GROUP_SLACK_MS) before touching it.
app.get('/api/admin/annual-slack-preview', requireOpsSecret, async (req, res) => {
  try {
    const rows = (await pool.query(`
      WITH first_saas AS (
        SELECT customer_name, MIN(date) AS first_date
          FROM invoices WHERE organization_id = $1 AND status NOT IN ('void','deleted') AND saas_amount > 0.005
         GROUP BY customer_name
      ),
      annual_invoices AS (
        SELECT DISTINCT i.id, i.invoice_number, i.customer_name, i.date, i.saas_amount, i.salesperson_name
          FROM invoices i CROSS JOIN LATERAL jsonb_array_elements(i.line_items) AS li
         WHERE i.organization_id = $1 AND i.status NOT IN ('void','deleted')
           AND i.line_items IS NOT NULL AND i.saas_amount > 0 AND li->>'type' = 'saas'
           AND (
             LOWER(TRIM(li->>'plan_code')) IN (SELECT LOWER(plan_code) FROM zoho_plans WHERE interval_unit ILIKE 'year%')
             OR li->>'name' ~* '(annual|annuel|yearly|par ann)'
           )
      )
      SELECT ai.invoice_number, ai.customer_name, ai.date::date AS annual_date,
             fs.first_date::date AS first_saas_date,
             (ai.date::date - fs.first_date::date) AS gap_days, ai.saas_amount::float AS saas_amount,
             ai.salesperson_name,
             COALESCE(s.is_active, false) AS rep_active, (s.name IS NULL) AS no_rep_row
        FROM annual_invoices ai JOIN first_saas fs ON fs.customer_name = ai.customer_name
        LEFT JOIN salespeople s ON s.name = ai.salesperson_name
       WHERE fs.first_date < ai.date AND (ai.date::date - fs.first_date::date) <= 45
       ORDER BY gap_days`, [process.env.ZOHO_ORG_ID])).rows;
    const payrollAffecting = rows.filter(r => r.salesperson_name !== 'Unassigned' && (r.rep_active || r.no_rep_row));
    res.json({
      count: rows.length, total_saas_amount: Math.round(rows.reduce((s, r) => s + r.saas_amount, 0) * 100) / 100,
      payroll_affecting_count: payrollAffecting.length,
      payroll_affecting_saas_amount: Math.round(payrollAffecting.reduce((s, r) => s + r.saas_amount, 0) * 100) / 100,
      rows,
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

