// GET /api/admin/rep-role-debug?secret=&name=<rep name>  — diagnoses "assigned a role but the
// Data Health 'reps with no role' card still flags them": shows exactly which login email the
// repsNoRole query resolves to (user_tokens.display_name match, else salespeople.email) and
// whether any user_roles row exists for THAT email — the two usually diverge on an accent/name
// mismatch between the Zoho display name and the salespeople row.
app.get('/api/admin/rep-role-debug', requireOpsSecret, async (req, res) => {
  const name = String(req.query.name || '').trim();
  if (!name) return res.status(400).json({ error: 'name required' });
  try {
    const sp = (await pool.query(`SELECT name, email, is_active FROM salespeople WHERE name ILIKE '%'||$1||'%'`, [name])).rows;
    const tokens = (await pool.query(`SELECT email, display_name, is_admin FROM user_tokens WHERE display_name ILIKE '%'||$1||'%'`, [name])).rows;
    const out = [];
    for (const s of sp) {
      const matchedToken = tokens.find(t => (t.display_name || '').toLowerCase() === s.name.toLowerCase());
      const resolvedEmail = (matchedToken && matchedToken.email) || s.email || null;
      const roles = resolvedEmail
        ? (await pool.query(
            `SELECT r.id, r.name FROM user_roles ur JOIN roles r ON r.id = ur.role_id WHERE LOWER(ur.user_email) = LOWER($1)`,
            [resolvedEmail]
          )).rows
        : [];
      out.push({
        salesperson: s,
        matchedUserToken: matchedToken || null,
        allTokensLike: tokens,
        resolvedLoginEmail: resolvedEmail,
        rolesForResolvedEmail: roles,
      });
    }
    res.json({ rows: out });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/invoice-payment-source?secret=&number=<invoice number>  — "which pay report
// was this invoice actually paid on?" Shows the invoices row's own approval/payout columns plus
// any commission_payment_lines row(s) joined to their import (filename, rep, period) — an
// invoice can only be in ONE commission_payment_lines row (the import that settled it), so this
// answers disputes like "Gabriella says X wasn't paid" definitively instead of guessing from
// commission_status alone.
app.get('/api/admin/invoice-payment-source', requireOpsSecret, async (req, res) => {
  const number = String(req.query.number || '').trim();
  if (!number) return res.status(400).json({ error: 'number required' });
  try {
    const inv = (await pool.query(
      `SELECT invoice_number, salesperson_name, organization_id, commission::float AS commission, commission_status,
              approval_status, approved_by, approved_at, payout_paid_by, payout_paid_at
         FROM invoices WHERE invoice_number = $1`, [number]
    )).rows[0] || null;
    const paymentLines = (await pool.query(
      `SELECT l.paid_amount::float AS paid_amount, l.app_commission::float AS app_commission,
              l.not_in_db, l.quota_partial, l.quota_forfeited::float AS quota_forfeited,
              i.id AS import_id, i.filename, i.rep_name, i.paid_for_period::date AS paid_for_period,
              i.imported_at, i.imported_by
         FROM commission_payment_lines l JOIN commission_payment_imports i ON i.id = l.import_id
        WHERE l.invoice_number = $1`, [number]
    )).rows;
    // Who excluded/restored/adjusted this invoice and when (activity_log) — explains e.g. a
    // commission_status='excluded' row that a rep is disputing.
    const activity = (await pool.query(
      `SELECT event_type, description, actor, amount::float AS amount, created_at
         FROM activity_log WHERE entity_type = 'invoice' AND entity_id = $1
        ORDER BY created_at DESC`, [number]
    )).rows;
    res.json({ invoice: inv, paymentLines, activity });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

