// GET /api/user/profile
app.get('/api/user/profile', authenticateToken, async (req, res) => {
  const { email } = req.user;
  try {
    const tokenResult = await pool.query(
      'SELECT email, photo, display_name, is_admin, created_at FROM user_tokens WHERE email = $1',
      [email]
    );
    const td = tokenResult.rows[0] || {};

    const prefResult = await pool.query(
      'SELECT language, currency, date_format, timezone FROM user_preferences WHERE email = $1',
      [email]
    );
    const prefs = prefResult.rows[0] || {};

    const repName = td.display_name || req.user.name || email;

    const statsResult = await pool.query(
      `SELECT COUNT(*) AS paid_invoices,
              COALESCE(SUM(commission), 0) AS total_commission,
              COALESCE(SUM(total), 0) AS total_revenue
       FROM invoices
       WHERE salesperson_name = $1 AND status = 'paid' AND organization_id = $2`,
      [repName, process.env.ZOHO_ORG_ID]
    );
    const stats = statsResult.rows[0] || {};

    const spResult = await pool.query(
      'SELECT name, is_active, commission_rate, signature_role, signature_role2, signature_phone FROM salespeople WHERE name = $1',
      [repName]
    );
    const sp = spResult.rows[0];

    // Assigned RBAC role names (for the read-only "Role" field on the profile).
    const roleRows = (await pool.query(
      `SELECT r.name FROM roles r JOIN user_roles ur ON ur.role_id = r.id
       WHERE LOWER(ur.user_email) = LOWER($1) ORDER BY r.name`, [email]
    )).rows;

    res.json({
      roles: roleRows.map(r => r.name),
      email: td.email || email,
      name: td.display_name || req.user.name || email,
      photo: td.photo || req.user.photo || null,
      isAdmin: td.is_admin != null ? td.is_admin : (req.user.isAdmin || false),
      preferences: {
        language:   prefs.language    || 'en',
        currency:   prefs.currency    || 'CAD',
        dateFormat: prefs.date_format || 'YYYY-MM-DD',
        timezone:   prefs.timezone    || 'America/Toronto',
      },
      salesperson: sp ? {
        name:           sp.name,
        isActive:       sp.is_active,
        commissionRate: parseFloat(sp.commission_rate) || 10,
        signatureRole:  sp.signature_role || null,
        signatureRole2: sp.signature_role2 || null,
        signaturePhone: sp.signature_phone || null,
      } : null,
      stats: {
        paidInvoices:    parseInt(stats.paid_invoices)    || 0,
        totalCommission: parseFloat(stats.total_commission) || 0,
        totalRevenue:    parseFloat(stats.total_revenue)   || 0,
      },
      memberSince: td.created_at || null,
    });
  } catch (error) {
    console.error('Profile error:', error);
    res.status(500).json({ error: 'Failed to fetch profile', details: error.message });
  }
});

// PUT /api/user/preferences
app.put('/api/user/preferences', authenticateToken, async (req, res) => {
  const { email } = req.user;
  const { language, currency, dateFormat, timezone } = req.body;
  try {
    // SECURITY: displayName is deliberately NOT writable here. user_tokens.display_name is the
    // rep-identity key that every rep-scoped query resolves against (pay stubs, commission
    // reports, /api/commissions, /api/invoices, resolveTargetRep). Letting a user set it freely
    // meant a rep could rename themselves to a colleague and be served that colleague's pay stub,
    // commission report and salary. Renaming a rep is an admin action — it belongs in
    // Admin → Salespeople, not in self-service preferences.
    await pool.query(
      `INSERT INTO user_preferences (email, language, currency, date_format, timezone)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (email) DO UPDATE SET
         language = $2, currency = $3, date_format = $4, timezone = $5,
         updated_at = CURRENT_TIMESTAMP`,
      [email, language || 'en', currency || 'CAD', dateFormat || 'YYYY-MM-DD', timezone || 'America/Toronto']
    );
    res.json({ success: true });
  } catch (error) {
    console.error('Preferences error:', error);
    res.status(500).json({ error: 'Failed to save preferences', details: error.message });
  }
});

// PUT /api/user/signature — self-service: a user sets their OWN email signature (role/role2/phone
// appended to proposal emails), resolved to their salespeople row the same way GET /api/user/profile
// does (by display name, not admin-gated). No-op with a clear error if the user isn't linked to a
// salesperson record yet (admin hasn't set them up in Admin -> Salespeople).
app.put('/api/user/signature', authenticateToken, async (req, res) => {
  const { email } = req.user;
  const role = (req.body.signatureRole || '').trim() || null;
  const role2 = (req.body.signatureRole2 || '').trim() || null;
  const phone = (req.body.signaturePhone || '').trim() || null;
  try {
    const tokenResult = await pool.query('SELECT display_name FROM user_tokens WHERE email = $1', [email]);
    const repName = tokenResult.rows[0]?.display_name || req.user.name || email;
    const r = await pool.query(
      `UPDATE salespeople SET signature_role = $1, signature_role2 = $2, signature_phone = $3, updated_at = CURRENT_TIMESTAMP
       WHERE name = $4 RETURNING name`,
      [role, role2, phone, repName]
    );
    if (r.rowCount === 0) return res.status(404).json({ error: 'No linked salesperson record — contact an admin to set one up first.' });
    res.json({ success: true });
  } catch (error) {
    console.error('Signature error:', error);
    res.status(500).json({ error: 'Failed to save signature', details: error.message });
  }
});

