// Fired right after a partner submits an opportunity. Never throws (fire-and-forget from the
// submission endpoint) — a mail failure must never affect the partner's own submission flow.
async function notifyNewPartnerOpportunity(partnerId, businessName, submittedByEmail) {
  try {
    const recipients = await getPartnerOpportunityRecipients();
    if (!recipients.length) return;
    const partner = (await pool.query(`SELECT name FROM partners WHERE id = $1`, [partnerId])).rows[0];
    const { subject, html } = newPartnerOpportunityEmail(businessName, partner?.name || 'Partner', submittedByEmail);
    await sendMail(recipients.join(','), subject, html);
  } catch (e) { console.warn('[partner-opp] notify failed:', e.message); }
}

// app_settings key 'partner_invoice_recipients' — accounting's inbox for partner invoices
// uploaded through SH-42. Separate audience from partner_opportunity_recipients (partner
// managers) — accounting only cares once there's money to actually pay out.
async function getPartnerInvoiceRecipients() {
  try {
    const r = await pool.query(`SELECT value FROM app_settings WHERE key = 'partner_invoice_recipients'`);
    const v = r.rows[0]?.value;
    return Array.isArray(v) ? v.filter(e => typeof e === 'string') : [];
  } catch { return []; }
}
app.get('/api/admin/partner-invoice-recipients', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'partners:manage'))) return;
  try { res.json({ recipients: await getPartnerInvoiceRecipients() }); }
  catch (e) { res.status(500).json({ error: e.message }); }
});
app.put('/api/admin/partner-invoice-recipients', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'partners:manage'))) return;
  const emails = Array.isArray(req.body?.emails) ? req.body.emails.map(e => String(e).trim().toLowerCase()).filter(Boolean) : null;
  if (!emails) return res.status(400).json({ error: 'emails array required' });
  if (emails.some(e => !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e))) return res.status(400).json({ error: 'invalid email' });
  try {
    await pool.query(
      `INSERT INTO app_settings (key, value, updated_at) VALUES ('partner_invoice_recipients', $1::jsonb, NOW())
       ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()`,
      [JSON.stringify(emails)]
    );
    res.json({ recipients: emails });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// The partner-invoice-uploaded email. Shared with the email-preview sample ('partner_invoice_uploaded').
function partnerInvoiceUploadedEmail(partnerName, periodLabel, totalAmount, fileName) {
  const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const base = process.env.FRONTEND_URL || 'https://saleshub.clusterpos.com';
  return {
    subject: `Facture partenaire reçue — ${partnerName} (${periodLabel})`,
    html: mailShell('Facture partenaire reçue / Partner invoice received',
      `<strong>${esc(partnerName)}</strong> a téléversé sa facture pour la période <strong>${esc(periodLabel)}</strong> (${totalAmount.toFixed(2)} $), fichier : ${esc(fileName)}.<br><br>` +
      `${esc(partnerName)} uploaded their invoice for period <strong>${esc(periodLabel)}</strong> ($${totalAmount.toFixed(2)}), file: ${esc(fileName)} — attached to this email.`,
      'Voir les partenaires / View partners', `${base}/admin/partners`),
  };
}

// Fired right after a Partner Admin uploads an invoice (SH-42). Attaches the file itself so
// accounting can act without logging into the admin panel. Never throws — fire-and-forget.
async function notifyPartnerInvoiceUploaded(invoiceId) {
  try {
    const recipients = await getPartnerInvoiceRecipients();
    if (!recipients.length) return;
    const row = (await pool.query(
      `SELECT pi.file_name, pi.mime_type, pi.file_data, p.name AS partner_name,
              r.period_label, r.total_amount
         FROM partner_invoices pi
         JOIN partners p ON p.id = pi.partner_id
         LEFT JOIN partner_payout_runs r ON r.id = pi.payout_run_id
        WHERE pi.id = $1`,
      [invoiceId]
    )).rows[0];
    if (!row) return;
    const { subject, html } = partnerInvoiceUploadedEmail(
      row.partner_name, row.period_label || 'N/A', row.total_amount ? parseFloat(row.total_amount) : 0, row.file_name
    );
    await sendMail(recipients.join(','), subject, html, {
      attachments: [{ filename: row.file_name, content: row.file_data, contentType: row.mime_type }],
    });
    await pool.query(`UPDATE partner_invoices SET forwarded_at = CURRENT_TIMESTAMP WHERE id = $1`, [invoiceId]);
  } catch (e) { console.warn('[partner-invoice] notify failed:', e.message); }
}

// Daily job: email the configured recipients when an active rep's probation ends in 45/30/15
// days. Deduped per (rep, end_date, threshold) so each milestone fires once.
async function checkProbationNotifications() {
  try {
    const recipients = await getProbationRecipients();
    if (!recipients.length) return;
    const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const reps = (await pool.query(`SELECT name, hire_date FROM salespeople WHERE is_active = true AND hire_date IS NOT NULL`)).rows;
    for (const r of reps) {
      const info = probationInfo(r.hire_date);
      if (!info.inProbation || ![45, 30, 15].includes(info.daysLeft)) continue;
      const ins = await pool.query(
        `INSERT INTO probation_notifications (rep_name, end_date, threshold) VALUES ($1, $2::date, $3)
         ON CONFLICT DO NOTHING RETURNING rep_name`, [r.name, info.endDate, info.daysLeft]);
      if (!ins.rows.length) continue; // already sent this milestone
      const html = mailShell(
        `Fin de probation dans ${info.daysLeft} jours / Probation ends in ${info.daysLeft} days`,
        `<strong>${esc(r.name)}</strong> — fin de probation le <strong>${info.endDate}</strong> (dans ${info.daysLeft} jours). Après cette date, le quota mensuel s'applique.<br><br>${esc(r.name)}'s new-hire probation ends on ${info.endDate} (in ${info.daysLeft} days). The monthly quota gate applies after that.`,
        null, null);
      await sendMail(recipients.join(','), `Probation — ${r.name} (J-${info.daysLeft})`, html);
    }
  } catch (e) { console.error('❌ [PROBATION] notification check error:', e.message); }
}

// Courriel envoyé au VENDEUR quand son signalement est résolu (demande utilisateur
// 2026-07-30). Jusqu'ici la boucle était à sens unique : il signalait, l'admin
// corrigeait, et personne ne le lui disait — donc il resignalait, ou pire, il
// pensait avoir été ignoré.
function reportResolvedEmail(r, note) {
  const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const isPoints = r.report_type === 'missing_points';
  const what = isPoints ? 'points manquants / missing points' : 'commission manquante / missing commission';
  const refLabel = isPoints ? 'Marchand / dossier · Merchant' : 'Facture · Invoice';
  const intro =
      `Bonne nouvelle — votre signalement de ${what} a été traité.<br>`
    + `Good news — your ${isPoints ? 'missing points' : 'missing commission'} report has been resolved.<br><br>`
    + (r.reference ? `<strong>${refLabel} :</strong> ${esc(r.reference)}<br>` : '')
    + (r.period ? `<strong>Période · Period :</strong> ${esc(r.period)}<br>` : '')
    + `<strong>Votre signalement · Your report :</strong><br>${esc(r.message).replace(/\n/g, '<br>')}<br><br>`
    // La note de l'admin est le vrai contenu utile : « corrigé » sans expliquer
    // quoi oblige le vendeur à aller vérifier lui-même.
    + (note
        ? `<strong>Réponse · Response :</strong><br>${esc(note).replace(/\n/g, '<br>')}<br><br>`
        : '')
    + `Les montants sont recalculés automatiquement — vérifiez votre rapport de commissions.<br>`
    + `Amounts are recalculated automatically — check your commission report.`;
  return {
    subject: isPoints ? 'Points manquants — résolu / resolved' : 'Commission manquante — résolue / resolved',
    html: mailShell('Signalement résolu / Report resolved', intro,
      'Voir mon rapport · View my report', `${process.env.FRONTEND_URL || ''}/commission-report`),
  };
}

// POST /api/admin/user-reports/:id/resolve — mark a user report (missing commission/points) resolved.
// Body (optionnel) : { note } — ce que l'admin veut dire au vendeur.
app.post('/api/admin/user-reports/:id/resolve', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'admin:data_health'))) return;
  try {
    const id = parseInt(req.params.id, 10);
    if (!id) return res.status(400).json({ error: 'invalid id' });
    const note = (req.body?.note || '').toString().trim().slice(0, 1000);
    // RETURNING plutôt qu'un SELECT séparé : une seule aller-retour, et on obtient
    // l'état d'AVANT-résolution sans course avec un autre admin.
    const row = (await pool.query(
      `UPDATE user_reports SET status = 'resolved', resolved_at = NOW(), resolved_by = $2
        WHERE id = $1 AND status <> 'resolved'
        RETURNING id, report_type, reporter_email, reporter_name, reference, period, message`,
      [id, req.user.email || req.user.name || 'admin']
    )).rows[0];
    _dataHealthCache = { at: 0, data: null };

    // Déjà résolu (double-clic, ou deux admins en même temps) : on ne renvoie pas
    // un second courriel au vendeur.
    if (!row) return res.json({ resolved: true, notified: false, reason: 'already_resolved' });

    let notified = false, reason = null;
    if (row.reporter_email) {
      try {
        const { subject, html } = reportResolvedEmail(row, note);
        const sent = await sendMail(row.reporter_email, subject, html);
        notified = !!sent.sent; reason = sent.reason || null;
      } catch (e) {
        // L'envoi qui échoue ne doit pas annuler la résolution : elle est faite,
        // et la reprocher à l'admin l'obligerait à recliquer sans effet.
        reason = e.message; console.warn('[user-report] notify failed:', e.message);
      }
    } else {
      reason = 'no_reporter_email';
    }
    await logActivity('user_report', id, 'resolved',
      `Signalement résolu${note ? ' avec réponse' : ''} — ${row.reporter_name || row.reporter_email || '?'}`,
      req.user.email || 'admin', { metadata: { reportType: row.report_type, notified, reason } });

    res.json({ resolved: true, notified, reason });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Build a lowercased key → canonical-reseller-name map from [{name, zentact_key, name_aliases}].
// A Zentact merchant's sales_rep_name / "Reseller" attribute matches a reseller by any of its
// zentact_key(s), its own name, OR any configured name alias (e.g. "Lirette" → "Lirette MG").
function buildResellerKeyMap(resellers) {
  const map = new Map();
  for (const rs of resellers) {
    for (const k of String(rs.zentact_key || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean)) {
      map.set(k, rs.name);
    }
    const nk = String(rs.name || '').trim().toLowerCase();
    if (nk && !map.has(nk)) map.set(nk, rs.name);
    for (const al of (Array.isArray(rs.name_aliases) ? rs.name_aliases : [])) {
      const ak = String(al || '').trim().toLowerCase();
      if (ak && !map.has(ak)) map.set(ak, rs.name);
    }
  }
  return map;
}

// GET /api/resellers/residuals — a reseller's Zentact SALES (merchants they activated),
// matched by the reseller's zentact_key against zentact_merchants.sales_rep_name
// (comma-separated, case-insensitive). Resellers don't get bonuses — this is their sales.
app.get('/api/resellers/residuals', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'reseller:view'))) return;
  try {
    // All resellers: matched by their zentact_key (sales_rep_name) AND/OR by name
    // against the Zentact "Reseller" custom attribute, so a reseller links even
    // before an admin sets its zentact_key.
    const resellers = (await pool.query(`SELECT name, zentact_key, name_aliases FROM resellers`)).rows;
    const merchants = (await pool.query(
      `SELECT zm.business_name, zm.status, zm.activated_at,
              LOWER(zm.sales_rep_name)     AS rep,
              LOWER(zm.reseller_attribute) AS reseller_attr,
              COALESCE(rev.profit_cents, 0) AS profit_cents
       FROM zentact_merchants zm
       LEFT JOIN (
         SELECT merchant_account_id, SUM(transaction_profit_cents) AS profit_cents
         FROM zentact_merchant_revenue GROUP BY merchant_account_id
       ) rev ON rev.merchant_account_id = zm.merchant_account_id
       WHERE (zm.sales_rep_name IS NOT NULL AND zm.sales_rep_name <> '')
          OR (zm.reseller_attribute IS NOT NULL AND zm.reseller_attribute <> '')`
    )).rows;

    // Match by sales_rep_name / "Reseller" attribute → canonical reseller (zentact_key, name, or alias).
    const keyToReseller = buildResellerKeyMap(resellers);

    const detail = [];
    const agg = new Map(); // reseller → { merchants, active, profit_cents }
    for (const m of merchants) {
      // Match by sales_rep_name first, then by the Reseller custom attribute.
      const reseller = keyToReseller.get(m.rep) || keyToReseller.get(m.reseller_attr);
      if (!reseller) continue; // not linked to a managed reseller (internal vendor / unmapped)
      const profit = Number(m.profit_cents) / 100;
      detail.push({ reseller_name: reseller, business_name: m.business_name, status: m.status, activated_at: m.activated_at, transaction_profit: profit });
      const a = agg.get(reseller) || { merchants: 0, active: 0, profit_cents: 0 };
      a.merchants++; if (m.status === 'ACTIVE') a.active++; a.profit_cents += Number(m.profit_cents) || 0;
      agg.set(reseller, a);
    }
    const byReseller = [...agg.entries()].map(([reseller_name, v]) => ({
      reseller_name, merchants: v.merchants, active: v.active, transaction_profit: v.profit_cents / 100,
    })).sort((a, b) => b.merchants - a.merchants);
    detail.sort((a, b) => new Date(b.activated_at || 0) - new Date(a.activated_at || 0));

    res.json({ connected: true, source: 'zentact', byReseller, sales: detail.slice(0, 2000), linkedResellers: resellers.length });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /api/zentact/revenue?year=YYYY — per-merchant monthly Transaction Profit for a
// year, with the salesperson and resolved reseller attached. Feeds the Revenus page
// (client filters by month + aggregates by rep / reseller).
app.get('/api/zentact/revenue', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'revenue:view'))) return;
  try {
    const year = parseInt(req.query.year) || new Date().getFullYear();
    // Reseller resolution map (same rules as /api/resellers/residuals).
    const resellers = (await pool.query(`SELECT name, zentact_key, name_aliases FROM resellers`)).rows;
    const keyToReseller = buildResellerKeyMap(resellers);
    const rows = (await pool.query(
      `SELECT r.merchant_account_id, r.month, r.transaction_profit_cents, r.total_volume_cents,
              r.other_revenue_cents, r.payments_count, r.currency, zm.business_name, zm.sales_rep_name,
              zm.stores, LOWER(zm.sales_rep_name) AS rep_l, LOWER(zm.reseller_attribute) AS reseller_attr_l
       FROM zentact_merchant_revenue r
       LEFT JOIN zentact_merchants zm ON zm.merchant_account_id = r.merchant_account_id
       WHERE r.year = $1`,
      [year]
    )).rows;
    const out = rows.map((r) => ({
      merchant_account_id: r.merchant_account_id,
      business_name: r.business_name || r.merchant_account_id,
      sales_rep_name: r.sales_rep_name || null,
      reseller_name: keyToReseller.get(r.rep_l) || keyToReseller.get(r.reseller_attr_l) || null,
      month: r.month,
      transaction_profit: Number(r.transaction_profit_cents) / 100,
      other_revenue: r.other_revenue_cents == null ? 0 : Number(r.other_revenue_cents) / 100,
      volume: Number(r.total_volume_cents) / 100,
      payments_count: r.payments_count,
      currency: r.currency,
      // Stores (locations) under this merchant — { storeId, storeReferenceId }.
      // Revenue is merchant-level (no per-store breakdown from Zentact); this is
      // for display so a multi-location merchant shows all its store names.
      stores: Array.isArray(r.stores)
        ? r.stores.map((s) => ({ storeId: s.storeId, storeReferenceId: s.storeReferenceId }))
        : [],
    }));
    const years = (await pool.query(`SELECT DISTINCT year FROM zentact_merchant_revenue ORDER BY year DESC`)).rows.map((x) => x.year);
    res.json({ year, years, rows: out });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /api/resellers/zentact-names — distinct Zentact sales_rep_names (+ merchant counts) to
// help the admin pick a reseller's zentact_key in the management tool.
app.get('/api/resellers/zentact-names', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'reseller:view'))) return;
  try {
    const r = await pool.query(
      `SELECT sales_rep_name AS name, COUNT(*)::int AS merchants
       FROM zentact_merchants WHERE sales_rep_name IS NOT NULL AND sales_rep_name <> ''
       GROUP BY 1 ORDER BY merchants DESC`
    );
    res.json({ names: r.rows });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

