async function getPayrollRecipients() {
  try {
    const r = await pool.query(`SELECT value FROM app_settings WHERE key = 'payroll_recipients'`);
    const v = r.rows[0]?.value;
    return Array.isArray(v) ? v.filter(e => typeof e === 'string') : [];
  } catch { return []; }
}

// Per-rep pay for a month: committed import total if present, else the generated model
// (unpaid qualifying commissions + signup + monthly-performance + processing bonuses).
async function payrollDataForMonth(year, month) {
  const mm = String(month).padStart(2, '0');
  const periodStart = new Date(`${year}-${mm}-01`);
  const periodEnd = new Date(periodStart); periodEnd.setMonth(periodEnd.getMonth() + 1);
  const orgId = process.env.ZOHO_ORG_ID;
  const platform = periodStart >= PLAN_START_DATE;
  const ptsMap = platform ? await getMonthlyPointsByRep(periodStart) : new Map();

  const reps = (await pool.query(`SELECT name, monthly_quota, signup_bonus_enabled, signup_bonus_amount FROM salespeople WHERE is_active = true ORDER BY name`)).rows;
  const out = [];
  for (const sp of reps) {
    const rep = sp.name;
    const imp = (await pool.query(
      `SELECT id, total_amount FROM commission_payment_imports
       WHERE rep_name = $1 AND paid_for_period >= $2::date AND paid_for_period < $3::date
       ORDER BY imported_at DESC LIMIT 1`, [rep, periodStart, periodEnd]
    )).rows[0];
    // The bi-annual processing bonus is deliberately excluded from the monthly payroll send —
    // it has its own dedicated statement/send flow, separate from regular monthly commissions
    // (2026-07-15, same change as GET /api/commissions/pay-stub).
    let lines = [], bonuses = [], total = 0, source;
    if (imp) {
      source = 'imported';
      lines = (await pool.query(
        `SELECT invoice_number, customer, paid_amount::float AS paid_amount, quota_partial, quota_forfeited::float AS quota_forfeited
         FROM commission_payment_lines
         WHERE import_id = $1 ORDER BY paid_amount DESC`, [imp.id])).rows;
      bonuses = (await pool.query(
        `SELECT bonus_type, merchant_name, amount::float AS amount FROM commission_bonuses
         WHERE import_id = $1 ORDER BY bonus_type`, [imp.id])).rows;
      total = parseFloat(imp.total_amount) || 0;
    } else {
      source = 'generated';
      lines = (await pool.query(
        `SELECT invoice_number, customer_name AS customer, commission::float AS paid_amount,
                (commission_status = 'quota_partial') AS quota_partial, quota_forfeited_amount::float AS quota_forfeited
         FROM invoices
         WHERE salesperson_name = $1 AND organization_id = $2
           AND commission_payable_date >= $3 AND commission_payable_date < $4
           AND commission > 0 AND commission_status IN ('hardware','saas_first','saas_annual','quota_partial')
           AND approval_status <> 'paid' ORDER BY commission DESC`,
        [rep, orgId, periodStart, periodEnd])).rows;
      // Signup bonus is the REP'S CURRENT config, not the stored (never-customized) bonus_amount.
      const signupCfg = { enabled: sp.signup_bonus_enabled !== false, amount: sp.signup_bonus_amount == null ? 100 : parseFloat(sp.signup_bonus_amount) };
      // UNE LIGNE PAR SUCCURSALE depuis le 1er aout 2026 (voir zentactUnits) — pas un montant
      // double sur une seule ligne : deux « Pile Ou Glace / 100 $ » identiques se lisent comme
      // une erreur de saisie, alors que « Pile Ou Glace — Pile_Ou_Glace_Ahuntsic » se verifie.
      //
      // LEFT JOIN LATERAL ... ON <condition> : quand la condition est fausse (activation
      // anterieure a la bascule), la jointure rend UNE ligne a NULL — le comportement d'avant,
      // a l'identique. Quand elle est vraie, une ligne par compte de solde distinct. Et si un
      // marchand n'a aucun magasin renseigne, le LEFT garantit quand meme sa ligne : une
      // structure incomplete cote Zentact ne doit pas faire disparaitre un boni.
      const signups = (await pool.query(
        `SELECT z.business_name AS merchant_name, succ.ref AS store_ref
           FROM zentact_merchants z
           LEFT JOIN LATERAL (
             SELECT DISTINCT ON (e->>'balanceAccountId')
                    e->>'balanceAccountId' AS ba, e->>'storeReferenceId' AS ref
               FROM jsonb_array_elements(COALESCE(z.stores, '[]'::jsonb)) e
              WHERE e->>'balanceAccountId' IS NOT NULL
           ) succ ON z.activated_at >= DATE '${ZENTACT_PER_STORE_FROM}'
          WHERE LOWER(z.sales_rep_name) = LOWER($1) AND z.status = 'ACTIVE'
            AND z.activated_at >= $2 AND z.activated_at < $3
          ORDER BY z.business_name, succ.ref`,
        [rep, periodStart, periodEnd])).rows;
      bonuses = signups.map(b => ({
        bonus_type: 'signup',
        // Le libelle ne porte la succursale que s'il y a matiere a distinguer : sur un marchand
        // a une seule adresse, « Chez Cookla — Cafe_Cremerie » n'apprend rien et alourdit.
        merchant_name: b.store_ref && signups.filter(x => x.merchant_name === b.merchant_name).length > 1
          ? `${b.merchant_name} — ${b.store_ref}`
          : b.merchant_name,
        amount: signupCfg.enabled ? signupCfg.amount : 0,
      }));
      if (platform) {
        const pts = ptsMap.get(`${rep}|${year}-${mm}`) || 0;
        const quota = sp.monthly_quota == null ? MONTHLY_QUOTA : parseInt(sp.monthly_quota);
        const mb = pts >= quota ? ZohoCRMService.calculateMonthlyBonus(pts) : 0;
        if (mb > 0) bonuses.push({ bonus_type: 'monthly_performance', merchant_name: `${pts} pts`, amount: mb });
      }
      const manual = (await pool.query(
        `SELECT amount::float AS amount, description FROM manual_bonuses
         WHERE rep_name = $1 AND period = $2::date`, [rep, periodStart]
      )).rows;
      for (const m of manual) bonuses.push({ bonus_type: 'manual', merchant_name: m.description, amount: m.amount });
      // Free-form (±) adjustments targeting this month (overpayment deductions etc.).
      const freeAdj = (await pool.query(
        `SELECT amount::float AS amount, description FROM commission_adjustments
         WHERE rep_name = $1 AND target_period = $2::date AND invoice_number IS NULL`,
        [rep, periodStart]
      )).rows;
      for (const a of freeAdj) bonuses.push({ bonus_type: 'adjustment', merchant_name: a.description, amount: a.amount });
      total = lines.reduce((s, l) => s + (l.paid_amount || 0), 0) + bonuses.reduce((s, b) => s + (b.amount || 0), 0);
    }
    total = Math.round(total * 100) / 100;
    if (total > 0 || lines.length || bonuses.length) out.push({ rep, source, lines, bonuses, total });
  }
  return out;
}

// All payroll email + PDF labels, by language. lang follows the admin's UI at send time;
// anything other than 'en' falls back to French (the default).
function payrollI18n(lang) {
  const en = String(lang || '').toLowerCase().startsWith('en');
  return en ? {
    emailSubject: 'Commissions payable', emailFooter: 'Detailed pay stubs attached (PDF). Gross amounts, before taxes and deductions.',
    by: 'by',
    payStubTitle: 'PAY STUB', rep: 'REP', period: 'PERIOD', status: 'STATUS', paid: 'Paid', pending: 'Pending approval',
    commissions: 'COMMISSIONS', invoice: 'INVOICE', customer: 'CUSTOMER', amount: 'AMOUNT', subtotalCommissions: 'Commissions subtotal',
    bonus: 'BONUSES', type: 'TYPE', detail: 'DETAIL', subtotalBonus: 'Bonus subtotal',
    adjustments: 'ADJUSTMENTS', subtotalAdjustments: 'Adjustments subtotal',
    totalPaid: 'TOTAL PAID', grossNote: 'Gross amounts, before taxes and deductions.',
    blSignup: 'Signup bonus', blMonthly: 'Monthly bonus', blProcessing: 'Processing bonus', blAdjustment: 'Adjustment',
  } : {
    emailSubject: 'Commissions à verser', emailFooter: 'Bulletins détaillés en pièce jointe (PDF). Montants bruts, avant impôts et retenues.',
    by: 'par',
    payStubTitle: 'BULLETIN DE PAIE', rep: 'VENDEUR', period: 'PÉRIODE', status: 'STATUT', paid: 'Payé', pending: "En attente d'approbation",
    commissions: 'COMMISSIONS', invoice: 'FACTURE', customer: 'CLIENT', amount: 'MONTANT', subtotalCommissions: 'Sous-total commissions',
    bonus: 'BONUS', type: 'TYPE', detail: 'DÉTAIL', subtotalBonus: 'Sous-total bonus',
    adjustments: 'AJUSTEMENTS', subtotalAdjustments: 'Sous-total ajustements',
    totalPaid: 'TOTAL VERSÉ', grossNote: 'Montants bruts, avant impôts et retenues.',
    blSignup: "Bonus d'inscription", blMonthly: 'Bonus mensuel', blProcessing: 'Bonus de processing', blAdjustment: 'Ajustement',
  };
}

// Build a single combined PDF (one rep per page) with pdfkit. Returns a Buffer.
// Le glyphe Sales Hub, dessine en VECTORIEL plutot qu'insere comme image.
//
// L'ancienne version posait `saleshub-mark-192.png` — la TUILE noire, celle du favicon — sur le
// bandeau bleu nuit des rapports. Une tuile sombre sur un fond sombre ne se lit pas : elle fait
// une tache. Le kit de marque le dit explicitement : sur une surface deja foncee on pose le
// glyphe NU, jamais la tuile (voir SalesHubLogo.tsx, variantes 'glyph'/'horizontal'/'lockup').
//
// Vectoriel plutot que PNG : net a l'impression quelle que soit la taille, et plus aucun fichier
// a embarquer avec le serveur. Le trace est celui du SVG de l'application, viewBox « 17 14 32 40 ».
// Renvoie la largeur occupee, pour que l'appelant pose le texte a cote sans deviner.
function drawSalesHubGlyph(doc, x, y, hauteur) {
  const e = hauteur / 40;                    // 40 = hauteur du viewBox
  doc.save();
  doc.translate(x, y).scale(e).translate(-17, -14);
  doc.path('M42 24 C42 18 24 18 24 26 C24 32.5 42 32 42 40 C42 48 24 48 23 41')
     .lineWidth(6).lineCap('round').strokeColor('#FFFFFF').stroke();
  doc.circle(42, 24, 4.5).fillColor('#F58345').fill();
  doc.restore();
  return 32 * e;                             // 32 = largeur du viewBox
}

// Le VERROUILLAGE de marque complet : glyphe + « Sales Hub » + « par cluster ● ».
//
// Le bandeau affichait « by Cluster Systems », qui n'est pas la signature de la marque. Celle-ci
// est composee de trois encres sur une meme ligne — « par » en gris, « cluster » en blanc gras,
// puis le point orange (voir SalesHubLogo.tsx, variante 'lockup').
//
// Les largeurs sont MESUREES (`widthOfString`) plutot que devinees : trois morceaux poses a des
// decalages fixes se desaligneraient des que le mot change de langue — « par » et « by » n'ont
// pas la meme largeur.
function drawSalesHubLockup(doc, x, y, T) {
  const gW = drawSalesHubGlyph(doc, x, y + 2, 32);
  const tx = x + gW + 12;
  doc.fillColor('#ffffff').font('Helvetica-Bold').fontSize(21).text('Sales Hub', tx, y + 2, { lineBreak: false });

  const by = (T && T.by ? T.by : 'by') + ' ';
  doc.fontSize(9);
  const wBy = doc.font('Helvetica').widthOfString(by);
  const wCluster = doc.font('Helvetica-Bold').widthOfString('cluster');
  const ly = y + 30;
  doc.fillColor('#8a99af').font('Helvetica').text(by, tx, ly, { lineBreak: false });
  doc.fillColor('#ffffff').font('Helvetica-Bold').text('cluster', tx + wBy, ly, { lineBreak: false });
  doc.circle(tx + wBy + wCluster + 5.5, ly + 3.4, 2.3).fillColor('#F58345').fill();
}

function buildPayrollPdf(periodLabel, reps, lang) {
  const T = payrollI18n(lang);
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({ size: 'LETTER', margin: 40 });
      const chunks = [];
      doc.on('data', c => chunks.push(c));
      doc.on('end', () => resolve(Buffer.concat(chunks)));
      const money = (n) => '$' + (Number(n) || 0).toLocaleString('en-CA', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      const bl = (t) => t === 'signup' ? T.blSignup : (t === 'monthly' || t === 'monthly_performance') ? T.blMonthly : t === 'processing' ? T.blProcessing : t === 'adjustment' ? T.blAdjustment : t;
      const L = 40, R = 572, W = R - L, AMT_X = R - 96;     // content area + amount column
      const C = { dark: '#1c2434', orange: '#f2682c', gray: '#475569', light: '#94a3b8', zebra: '#fafbfd', line: '#e8edf3' };
      const ensure = (h) => { if (doc.y + h > 748) doc.addPage(); };
      const header = (r) => {
        doc.rect(0, 0, 612, 6).fill(C.orange);
        doc.rect(0, 6, 612, 74).fill(C.dark);
        drawSalesHubLockup(doc, L, 22, T);
        doc.fillColor(C.orange).font('Helvetica-Bold').fontSize(9).text(T.payStubTitle, L, 26, { width: W, align: 'right', characterSpacing: 1.5 });
        doc.fillColor('#ffffff').font('Helvetica-Bold').fontSize(17).text(periodLabel, L, 42, { width: W, align: 'right' });
        // meta row
        const my = 96;
        const meta = [[T.rep, r.rep], [T.period, periodLabel], [T.status, r.source === 'imported' ? T.paid : T.pending]];
        const cw = W / 3;
        meta.forEach((m, i) => {
          const x = L + i * cw;
          doc.fillColor(C.light).font('Helvetica-Bold').fontSize(7).text(m[0], x, my, { characterSpacing: 1 });
          doc.fillColor(C.dark).font('Helvetica-Bold').fontSize(11).text(m[1], x, my + 11, { width: cw - 8 });
        });
        doc.y = my + 40;
        doc.moveTo(L, doc.y).lineTo(R, doc.y).strokeColor(C.line).lineWidth(1).stroke();
        doc.y += 16;
      };

      const sectionHead = (title, c0, c1) => {
        ensure(46);
        doc.fillColor(C.orange).font('Helvetica-Bold').fontSize(9).text(title, L, doc.y, { characterSpacing: 1.5 });
        doc.y += 15;
        const hy = doc.y;
        doc.fillColor(C.light).font('Helvetica-Bold').fontSize(7);
        doc.text(c0, L + 2, hy, { characterSpacing: 0.5 });
        doc.text(c1, L + 130, hy, { characterSpacing: 0.5 });
        doc.text(T.amount, AMT_X, hy, { width: 92, align: 'right', characterSpacing: 0.5 });
        doc.y = hy + 11;
        doc.moveTo(L, doc.y).lineTo(R, doc.y).strokeColor(C.dark).lineWidth(1).stroke();
        doc.y += 5;
      };
      const row = (c0, c1, amt, i, neg, badgePct) => {
        ensure(18);
        const y = doc.y;
        if (i % 2) doc.rect(L, y - 3, W, 17).fill(C.zebra);
        doc.fillColor(C.dark).font('Helvetica').fontSize(9).text(String(c0 || ''), L + 2, y, { width: 122, ellipsis: true });
        const custW = AMT_X - (L + 130) - (badgePct != null ? 40 : 8);
        doc.fillColor(C.gray).text(String(c1 || '—'), L + 130, y, { width: custW, ellipsis: true });
        // Quota-gate partial-release marker — a rep should see WHY this line is less than
        // the full commission, not just a smaller number (user report 2026-07-08).
        if (badgePct != null) {
          const bx = AMT_X - 34, bw = 30;
          doc.roundedRect(bx, y - 1, bw, 12, 3).fill('#fff1e8');
          doc.fillColor(C.orange).font('Helvetica-Bold').fontSize(6.5).text(`${badgePct}%`, bx, y + 1.5, { width: bw, align: 'center' });
        }
        doc.fillColor(neg ? '#d34053' : C.dark).font('Helvetica-Bold').fontSize(9).text(amt, AMT_X, y, { width: 92, align: 'right' });
        doc.y = y + 17;
      };
      const subtotal = (label, amt, neg) => {
        doc.moveTo(L, doc.y).lineTo(R, doc.y).strokeColor(C.dark).lineWidth(1).stroke();
        doc.y += 5;
        const y = doc.y;
        doc.fillColor(C.gray).font('Helvetica-Bold').fontSize(8).text(label.toUpperCase(), L, y, { width: AMT_X - L - 8, align: 'right', characterSpacing: 0.5 });
        doc.fillColor(neg ? '#d34053' : C.dark).fontSize(10).text(amt, AMT_X, y - 1, { width: 92, align: 'right' });
        doc.y = y + 18;
      };

      reps.forEach((r, idx) => {
        if (idx > 0) doc.addPage();
        header(r);
        if (r.lines.length) {
          sectionHead(T.commissions, T.invoice, T.customer);
          r.lines.forEach((l, i) => {
            const pct = l.quota_partial ? Math.round((l.paid_amount / ((l.paid_amount || 0) + (l.quota_forfeited || 0))) * 100) : null;
            row(l.invoice_number, l.customer, money(l.paid_amount), i, false, pct);
          });
          subtotal(T.subtotalCommissions, money(r.lines.reduce((s, l) => s + (l.paid_amount || 0), 0)));
        }
        // Adjustments (corrections on past periods) print in their OWN section, after bonuses.
        const realBonuses = r.bonuses.filter(b => b.bonus_type !== 'adjustment');
        const adjustments = r.bonuses.filter(b => b.bonus_type === 'adjustment');
        if (realBonuses.length) {
          doc.y += 8;
          sectionHead(T.bonus, T.type, T.detail);
          realBonuses.forEach((b, i) => row(bl(b.bonus_type), b.merchant_name, money(b.amount), i));
          subtotal(T.subtotalBonus, money(realBonuses.reduce((s, b) => s + (b.amount || 0), 0)));
        }
        if (adjustments.length) {
          doc.y += 8;
          sectionHead(T.adjustments, T.type, T.detail);
          adjustments.forEach((b, i) => row(bl(b.bonus_type), b.merchant_name, money(b.amount), i, (b.amount || 0) < 0));
          const adjSum = adjustments.reduce((s, b) => s + (b.amount || 0), 0);
          subtotal(T.subtotalAdjustments, money(adjSum), adjSum < 0);
        }
        // TOTAL box
        ensure(60);
        doc.y += 12;
        const by = doc.y, bx = R - 268;
        doc.roundedRect(bx, by, 268, 40, 9).fillAndStroke('#fff4ec', '#f7c8ab');
        doc.fillColor(C.orange).font('Helvetica-Bold').fontSize(9).text(T.totalPaid, bx + 16, by + 15, { characterSpacing: 1 });
        doc.fillColor(C.dark).font('Helvetica-Bold').fontSize(18).text(money(r.total), bx + 16, by + 11, { width: 236, align: 'right' });
        doc.y = by + 56;
        doc.fillColor(C.light).font('Helvetica-Oblique').fontSize(7.5).text(T.grossNote, L, doc.y, { continued: true })
          .font('Helvetica').text('     Sales Hub · saleshub.clusterpos.com', { align: 'left' });
      });
      doc.end();
    } catch (e) { reject(e); }
  });
}

// Build a combined PDF (one rep per page) for the bi-annual PROCESSING bonus specifically —
// deliberately its own, clearly-labeled document rather than reusing buildPayrollPdf, whose
// header always says "Pay Stub" (would undermine the point of separating the two). reps:
// [{ rep, accounts: [{merchant_name, amount}], total }].
function buildProcessingBonusPdf(periodLabel, reps, lang) {
  const en = String(lang || '').toLowerCase().startsWith('en');
  const T = en
    ? { docTitle: 'BI-ANNUAL PROCESSING BONUS', rep: 'REP', period: 'PERIOD', merchant: 'MERCHANT', amount: 'AMOUNT', totalPaid: 'TOTAL PAID', note: 'One-time bi-annual bonus tied to Zentact merchant processing volume — separate from regular monthly commissions.' }
    : { docTitle: 'BONUS DE VOLUME BI-ANNUEL', rep: 'VENDEUR', period: 'PÉRIODE', merchant: 'MARCHAND', amount: 'MONTANT', totalPaid: 'TOTAL VERSÉ', note: 'Bonus bi-annuel unique lié au volume de traitement des marchands Zentact — distinct des commissions mensuelles régulières.' };
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({ size: 'LETTER', margin: 40 });
      const chunks = [];
      doc.on('data', c => chunks.push(c));
      doc.on('end', () => resolve(Buffer.concat(chunks)));
      const money = (n) => '$' + (Number(n) || 0).toLocaleString('en-CA', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      const L = 40, R = 572, W = R - L, AMT_X = R - 96;
      const C = { dark: '#1c2434', orange: '#f2682c', gray: '#475569', light: '#94a3b8', zebra: '#fafbfd', line: '#e8edf3' };
      const ensure = (h) => { if (doc.y + h > 748) doc.addPage(); };
      reps.forEach((r, idx) => {
        if (idx > 0) doc.addPage();
        doc.rect(0, 0, 612, 6).fill(C.orange);
        doc.rect(0, 6, 612, 74).fill(C.dark);
        drawSalesHubLockup(doc, L, 22, T);
        doc.fillColor(C.orange).font('Helvetica-Bold').fontSize(9).text(T.docTitle, L, 26, { width: W, align: 'right', characterSpacing: 1.5 });
        doc.fillColor('#ffffff').font('Helvetica-Bold').fontSize(17).text(periodLabel, L, 42, { width: W, align: 'right' });
        const my = 96;
        [[T.rep, r.rep], [T.period, periodLabel]].forEach((m, i) => {
          const x = L + i * (W / 2);
          doc.fillColor(C.light).font('Helvetica-Bold').fontSize(7).text(m[0], x, my, { characterSpacing: 1 });
          doc.fillColor(C.dark).font('Helvetica-Bold').fontSize(11).text(m[1], x, my + 11, { width: W / 2 - 8 });
        });
        doc.y = my + 40;
        doc.moveTo(L, doc.y).lineTo(R, doc.y).strokeColor(C.line).lineWidth(1).stroke();
        doc.y += 16;

        ensure(46);
        doc.fillColor(C.orange).font('Helvetica-Bold').fontSize(9).text(T.merchant, L, doc.y, { characterSpacing: 1.5 });
        doc.y += 15;
        const hy = doc.y;
        doc.fillColor(C.light).font('Helvetica-Bold').fontSize(7);
        doc.text(T.merchant, L + 2, hy, { characterSpacing: 0.5 });
        doc.text(T.amount, AMT_X, hy, { width: 92, align: 'right', characterSpacing: 0.5 });
        doc.y = hy + 11;
        doc.moveTo(L, doc.y).lineTo(R, doc.y).strokeColor(C.dark).lineWidth(1).stroke();
        doc.y += 5;
        (r.accounts || []).forEach((a, i) => {
          ensure(18);
          const y = doc.y;
          if (i % 2) doc.rect(L, y - 3, W, 17).fill(C.zebra);
          doc.fillColor(C.dark).font('Helvetica').fontSize(9).text(String(a.merchant_name || '—'), L + 2, y, { width: AMT_X - L - 10, ellipsis: true });
          doc.fillColor(C.dark).font('Helvetica-Bold').fontSize(9).text(money(a.amount), AMT_X, y, { width: 92, align: 'right' });
          doc.y = y + 17;
        });

        ensure(60);
        doc.y += 12;
        const by = doc.y, bx = R - 268;
        doc.roundedRect(bx, by, 268, 40, 9).fillAndStroke('#fff4ec', '#f7c8ab');
        doc.fillColor(C.orange).font('Helvetica-Bold').fontSize(9).text(T.totalPaid, bx + 16, by + 15, { characterSpacing: 1 });
        doc.fillColor(C.dark).font('Helvetica-Bold').fontSize(18).text(money(r.total), bx + 16, by + 11, { width: 236, align: 'right' });
        doc.y = by + 56;
        doc.fillColor(C.light).font('Helvetica-Oblique').fontSize(7.5).text(T.note, L, doc.y, { width: W, continued: true })
          .font('Helvetica').text('     Sales Hub · saleshub.clusterpos.com', { align: 'left' });
      });
      doc.end();
    } catch (e) { reject(e); }
  });
}

// GET /api/commissions/annual-reconciliation?year= — year-end books check: for every active
// rep × month, what was PAID (pay-file/commit ledger) vs what the model CALCULATES vs the
// delta. Pre-platform months (< May 2026) differ BY DESIGN (imported reports were the truth).
app.get('/api/commissions/annual-reconciliation', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'report:annual_reconciliation'))) return;
  const year = parseInt(req.query.year) || new Date().getFullYear();
  const yearStart = `${year}-01-01`, yearEnd = `${year + 1}-01-01`;
  const orgId = process.env.ZOHO_ORG_ID;
  try {
    const reps = (await pool.query(
      `SELECT name, monthly_quota FROM salespeople WHERE is_active = true ORDER BY name`)).rows;

    // PAID: the latest import per rep+month (same pick as payroll/pay-stub)…
    const paidRows = (await pool.query(`
      SELECT rep_name, to_char(paid_for_period, 'YYYY-MM') AS ym, total_amount::float AS total
        FROM (SELECT rep_name, paid_for_period, total_amount,
                     ROW_NUMBER() OVER (PARTITION BY rep_name, date_trunc('month', paid_for_period)
                                        ORDER BY imported_at DESC) AS rn
                FROM commission_payment_imports
               WHERE paid_for_period >= $1::date AND paid_for_period < $2::date) x
       WHERE rn = 1`, [yearStart, yearEnd])).rows;
    // …plus accepted bi-annual processing payouts (committed outside imports) — they are both
    // paid AND part of the model, so they land on BOTH sides (no artificial delta).
    const procRows = (await pool.query(`
      SELECT rep_name, to_char(paid_for_period, 'YYYY-MM') AS ym, SUM(amount)::float AS total
        FROM commission_bonuses
       WHERE bonus_type = 'processing' AND import_id IS NULL
         AND paid_for_period >= $1::date AND paid_for_period < $2::date
       GROUP BY 1, 2`, [yearStart, yearEnd])).rows;

    // CALCULATED: the model's value for the month (mirrors the generated pay stub).
    const invRows = (await pool.query(`
      SELECT salesperson_name AS rep, to_char(commission_payable_date, 'YYYY-MM') AS ym,
             SUM(commission)::float AS total
        FROM invoices
       WHERE organization_id = $3 AND commission > 0
         AND commission_status IN ('hardware','saas_first','saas_annual','quota_partial')
         AND commission_payable_date >= $1::date AND commission_payable_date < $2::date
       GROUP BY 1, 2`, [yearStart, yearEnd, orgId])).rows;
    // Signup bonus is the rep's CURRENT config, not the stored (never-customized) bonus_amount.
    const signupRows = (await pool.query(`
      SELECT LOWER(zm.sales_rep_name) AS rep, to_char(zm.activated_at, 'YYYY-MM') AS ym,
             SUM(CASE WHEN sp.signup_bonus_enabled IS FALSE THEN 0 ELSE COALESCE(sp.signup_bonus_amount, 100) END)::float AS total
        FROM zentact_merchants zm
        LEFT JOIN salespeople sp ON LOWER(sp.name) = LOWER(zm.sales_rep_name)
       WHERE zm.status = 'ACTIVE' AND zm.sales_rep_name IS NOT NULL
         AND zm.activated_at >= $1::date AND zm.activated_at < $2::date
       GROUP BY 1, 2`, [yearStart, yearEnd])).rows;
    const manualRows = (await pool.query(`
      SELECT rep_name, to_char(period, 'YYYY-MM') AS ym, SUM(amount)::float AS total
        FROM manual_bonuses WHERE period >= $1::date AND period < $2::date
       GROUP BY 1, 2`, [yearStart, yearEnd])).rows;
    const freeAdjRows = (await pool.query(`
      SELECT rep_name, to_char(target_period, 'YYYY-MM') AS ym, SUM(amount)::float AS total
        FROM commission_adjustments
       WHERE invoice_number IS NULL AND target_period >= $1::date AND target_period < $2::date
       GROUP BY 1, 2`, [yearStart, yearEnd])).rows;
    // One pass covers every month of the year (map is keyed rep|YYYY-MM).
    const ptsMap = await getMonthlyPointsByRep(new Date(yearStart));

    const key = (rep, ym) => `${rep}|${ym}`;
    const toMap = (rows, repCol = 'rep_name') => {
      const m = new Map();
      for (const r of rows) m.set(key(r[repCol] ?? r.rep, r.ym), r.total || 0);
      return m;
    };
    const paidMap = toMap(paidRows), procMap = toMap(procRows), invMap = toMap(invRows, 'rep'),
          manualMap = toMap(manualRows), adjMap = toMap(freeAdjRows);
    const signupMap = toMap(signupRows, 'rep'); // keyed by LOWER(rep)

    const platformFrom = '2026-05'; // the platform pays from May 2026; before = imported truth
    const round2 = (n) => Math.round(n * 100) / 100;
    const out = [];
    for (const sp of reps) {
      const rep = sp.name;
      const quota = sp.monthly_quota == null ? MONTHLY_QUOTA : parseInt(sp.monthly_quota);
      const months = [];
      let paidY = 0, calcY = 0;
      for (let m = 1; m <= 12; m++) {
        const ym = `${year}-${String(m).padStart(2, '0')}`;
        const proc = procMap.get(key(rep, ym)) || 0;
        const paid = (paidMap.get(key(rep, ym)) || 0) + proc;
        let calc = (invMap.get(key(rep, ym)) || 0)
                 + (signupMap.get(key(rep.toLowerCase(), ym)) || 0)
                 + (manualMap.get(key(rep, ym)) || 0)
                 + (adjMap.get(key(rep, ym)) || 0)
                 + proc;
        if (ym >= platformFrom) {
          const pts = ptsMap.get(`${rep}|${ym}`) || 0;
          if (pts >= quota) calc += ZohoCRMService.calculateMonthlyBonus(pts);
        }
        paidY += paid; calcY += calc;
        months.push({ month: m, paid: round2(paid), calculated: round2(calc), delta: round2(paid - calc) });
      }
      if (Math.abs(paidY) < 0.005 && Math.abs(calcY) < 0.005) continue; // nothing all year
      out.push({ rep, months, totals: { paid: round2(paidY), calculated: round2(calcY), delta: round2(paidY - calcY) } });
    }
    const grand = {
      paid: round2(out.reduce((s, r) => s + r.totals.paid, 0)),
      calculated: round2(out.reduce((s, r) => s + r.totals.calculated, 0)),
      delta: round2(out.reduce((s, r) => s + r.totals.delta, 0)),
    };
    res.json({ year, platformFrom, reps: out, grand });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/commissions/payroll/preview?year=&month= — per-rep totals + the calendar deadline.
app.get('/api/commissions/payroll/preview', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'report:mark_paid'))) return;
  const year = parseInt(req.query.year), month = parseInt(req.query.month);
  if (!year || month < 1 || month > 12) return res.status(400).json({ error: 'year + month required' });
  try {
    const reps = await payrollDataForMonth(year, month);
    const mm = String(month).padStart(2, '0');
    // Deadline = the "commission due by" of the LAST pay period whose end falls in the month.
    const inMonth = PAY_CALENDAR.filter(p => p[1].startsWith(`${year}-${mm}`));
    const dueBy = inMonth.length ? inMonth[inMonth.length - 1][2] : null;
    // Latest payroll-send timestamp per rep for this period (for the "Sent" badge).
    const sentMap = new Map(
      (await pool.query(
        `SELECT rep_name, MAX(sent_at) AS sent_at FROM payroll_sends WHERE period = $1::date GROUP BY rep_name`,
        [`${year}-${mm}-01`]
      )).rows.map(r => [r.rep_name, r.sent_at])
    );
    res.json({
      year, month, dueBy,
      recipients: await getPayrollRecipients(),
      grandTotal: Math.round(reps.reduce((s, r) => s + r.total, 0) * 100) / 100,
      reps: reps.map(r => ({ rep: r.rep, source: r.source, total: r.total, lineCount: r.lines.length, bonusCount: r.bonuses.length, sentAt: sentMap.get(r.rep) || null })),
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /api/commissions/payroll/recipients — the saved payroll recipient list.
app.get('/api/commissions/payroll/recipients', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'report:mark_paid'))) return;
  try {
    res.json({ recipients: await getPayrollRecipients() });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// PUT /api/commissions/payroll/recipients { emails:[...] }
app.put('/api/commissions/payroll/recipients', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'report:mark_paid'))) return;
  const emails = Array.isArray(req.body?.emails) ? req.body.emails.map(e => String(e).trim().toLowerCase()).filter(Boolean) : null;
  if (!emails) return res.status(400).json({ error: 'emails array required' });
  if (emails.some(e => !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e))) return res.status(400).json({ error: 'invalid email' });
  try {
    await pool.query(
      `INSERT INTO app_settings (key, value, updated_at) VALUES ('payroll_recipients', $1::jsonb, NOW())
       ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()`,
      [JSON.stringify(emails)]
    );
    res.json({ recipients: emails });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// POST /api/commissions/payroll/send { year, month } — email payroll the month's commissions:
// a summary table in the body + one combined PDF (all reps, one per page).
app.post('/api/commissions/payroll/send', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'report:mark_paid'))) return;
  const year = parseInt(req.body.year), month = parseInt(req.body.month);
  if (!year || month < 1 || month > 12) return res.status(400).json({ error: 'year + month required' });
  try {
    const recipients = await getPayrollRecipients();
    if (!recipients.length) return res.status(400).json({ error: 'no payroll recipients configured' });
    let reps = await payrollDataForMonth(year, month);
    // Optional multi-select: send only the chosen reps (default = all).
    const repFilter = Array.isArray(req.body.reps) ? req.body.reps.map(s => String(s)) : null;
    if (repFilter && repFilter.length) reps = reps.filter(r => repFilter.includes(r.rep));
    if (!reps.length) return res.status(400).json({ error: 'nothing to send for this period' });
    const mm = String(month).padStart(2, '0');
    const periodLabel = `${year}-${mm}`;
    const T = payrollI18n(req.body.lang);   // language follows the admin's UI at send time
    const money = (n) => '$' + (Number(n) || 0).toLocaleString('en-CA', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const grand = Math.round(reps.reduce((s, r) => s + r.total, 0) * 100) / 100;
    const rowsHtml = reps.map(r =>
      `<tr><td style="padding:6px 10px;border-top:1px solid #eef1f6">${r.rep}</td>
           <td style="padding:6px 10px;border-top:1px solid #eef1f6;text-align:right">${money(r.total)}</td></tr>`).join('');
    const inner = `<h1 style="margin:0 0 14px;color:#0f1722;font-size:20px;font-weight:700;line-height:1.3">${T.emailSubject} — ${periodLabel}</h1>
            <table width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#1c2434;border-collapse:collapse">
              <tr><th style="text-align:left;padding:6px 10px;color:#94a3b8;font-size:11px;letter-spacing:.4px">${T.rep}</th><th style="text-align:right;padding:6px 10px;color:#94a3b8;font-size:11px;letter-spacing:.4px">${T.amount}</th></tr>
              ${rowsHtml}
              <tr><td style="padding:10px;border-top:2px solid #0f1722;font-weight:700">${T.totalPaid}</td><td style="padding:10px;border-top:2px solid #0f1722;text-align:right;font-weight:700;color:#f97316">${money(grand)}</td></tr>
            </table>
            <p style="margin:18px 0 0;color:#94a3b8;font-size:11px">${T.emailFooter}</p>`;
    const html = mailChrome(inner, `${T.emailSubject} — ${periodLabel}`);
    const pdf = await buildPayrollPdf(periodLabel, reps, req.body.lang);
    const t = getMailer();
    if (!t) return res.status(502).json({ error: 'smtp_not_configured' });
    await t.sendMail({
      from: process.env.SMTP_FROM || process.env.SMTP_USER,
      to: recipients.join(','),
      subject: `${T.emailSubject} — ${periodLabel}`,
      html,
      attachments: [{ filename: `Commissions_${periodLabel}.pdf`, content: pdf }],
    });
    // Log the send per rep so the preview can show a "Sent" badge + the history can list batches.
    // Single multi-row INSERT → all rows share one CURRENT_TIMESTAMP, so a batch groups cleanly by sent_at.
    const periodDate = `${year}-${mm}-01`;
    const sentBy = req.user.realAdminEmail || req.user.email || 'unknown';
    const sentTo = recipients.join(', ');
    const values = [], params = [];
    reps.forEach((r, i) => {
      const b = i * 5;
      values.push(`($${b + 1}, $${b + 2}::date, $${b + 3}, $${b + 4}, $${b + 5})`);
      params.push(r.rep, periodDate, sentTo, sentBy, Math.round((Number(r.total) || 0) * 100) / 100);
    });
    await pool.query(
      `INSERT INTO payroll_sends (rep_name, period, sent_to, sent_by, total) VALUES ${values.join(', ')}`,
      params
    );
    res.json({ sent: true, recipients: recipients.length, reps: reps.length, grandTotal: grand });
  } catch (e) {
    // Le motif part MAINTENANT dans les deux directions : le journal du serveur (avec la pile,
    // pour retrouver la ligne fautive) et le message rendu a l'admin. L'ancienne version ne
    // faisait ni l'un ni l'autre : `details` n'etait affiche nulle part et rien n'etait journalise.
    console.error('[payroll-send] echec de l envoi:', e.stack || e.message);
    res.status(500).json({ error: `Failed to send payroll: ${e.message}`, details: e.message });
  }
});

// POST /api/commissions/processing-bonus/send { year, month }  (month must be 6 or 12)
// Emails the payroll team the ALREADY-COMMITTED bi-annual processing bonus for a period — its
// own send action, own PDF, own history table (processing_bonus_sends), deliberately never
// mixed with the regular monthly "Payroll -> send" flow (2026-07-15). Uses the same payroll
// recipients list, since it's the same team, just a distinct notification.
// GET /api/commissions/processing-bonus/committed?year=&month=  (month must be 6 or 12)
// Read-only per-rep breakdown of the ALREADY-COMMITTED bi-annual bonus for a period — what the
// send action below would actually email, without sending anything.
app.get('/api/commissions/processing-bonus/committed', requireOpsSecretOrSession, async (req, res) => {
  if (!req.viaSecret && !(await requirePerm(req, res, 'report:mark_paid'))) return;
  const year = parseInt(req.query.year), month = parseInt(req.query.month);
  if (!year || (month !== 6 && month !== 12)) return res.status(400).json({ error: 'year + month (6 or 12) required' });
  try {
    const period = `${year}-${String(month).padStart(2, '0')}-01`;
    const rows = (await pool.query(
      `SELECT rep_name, merchant_name, amount::float AS amount FROM commission_bonuses
        WHERE bonus_type = 'processing' AND import_id IS NULL AND paid_for_period = $1::date
        ORDER BY rep_name, amount DESC`,
      [period]
    )).rows;
    const byRep = new Map();
    for (const r of rows) {
      if (!byRep.has(r.rep_name)) byRep.set(r.rep_name, { rep: r.rep_name, accounts: [], total: 0 });
      const e = byRep.get(r.rep_name);
      e.accounts.push({ merchant_name: r.merchant_name, amount: r.amount });
      e.total = Math.round((e.total + r.amount) * 100) / 100;
    }
    const reps = [...byRep.values()].sort((a, b) => b.total - a.total);
    const lastSent = (await pool.query(
      `SELECT rep_name, MAX(sent_at) AS sent_at FROM processing_bonus_sends WHERE period = $1::date GROUP BY rep_name`,
      [period]
    )).rows;
    const sentByRep = new Map(lastSent.map(r => [r.rep_name, r.sent_at]));
    reps.forEach(r => { r.sentAt = sentByRep.get(r.rep) || null; });
    res.json({ year, month, reps, grandTotal: Math.round(reps.reduce((s, r) => s + r.total, 0) * 100) / 100 });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/commissions/processing-bonus/send', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'report:mark_paid'))) return;
  const year = parseInt(req.body.year), month = parseInt(req.body.month);
  if (!year || (month !== 6 && month !== 12)) return res.status(400).json({ error: 'year + month (6 or 12) required' });
  try {
    const recipients = await getPayrollRecipients();
    if (!recipients.length) return res.status(400).json({ error: 'no payroll recipients configured' });
    const period = `${year}-${String(month).padStart(2, '0')}-01`;
    const rows = (await pool.query(
      `SELECT rep_name, merchant_name, amount::float AS amount FROM commission_bonuses
        WHERE bonus_type = 'processing' AND import_id IS NULL AND paid_for_period = $1::date
        ORDER BY rep_name, amount DESC`,
      [period]
    )).rows;
    const byRep = new Map();
    for (const r of rows) {
      if (!byRep.has(r.rep_name)) byRep.set(r.rep_name, { rep: r.rep_name, accounts: [], total: 0 });
      const e = byRep.get(r.rep_name);
      e.accounts.push({ merchant_name: r.merchant_name, amount: r.amount });
      e.total = Math.round((e.total + r.amount) * 100) / 100;
    }
    let reps = [...byRep.values()];
    const repFilter = Array.isArray(req.body.reps) ? req.body.reps.map(String) : null;
    if (repFilter && repFilter.length) reps = reps.filter(r => repFilter.includes(r.rep));
    if (!reps.length) return res.status(400).json({ error: 'nothing committed to send for this period' });
    const periodLabel = `${year}-${String(month).padStart(2, '0')}`;
    const en = String(req.body.lang || '').toLowerCase().startsWith('en');
    const money = (n) => '$' + (Number(n) || 0).toLocaleString('en-CA', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const grand = Math.round(reps.reduce((s, r) => s + r.total, 0) * 100) / 100;
    const subject = en ? `Bi-Annual Processing Bonus — ${periodLabel}` : `Bonus de volume bi-annuel — ${periodLabel}`;
    const rowsHtml = reps.map(r =>
      `<tr><td style="padding:6px 10px;border-top:1px solid #eef1f6">${r.rep}</td>
           <td style="padding:6px 10px;border-top:1px solid #eef1f6;text-align:right">${money(r.total)}</td></tr>`).join('');
    const inner = `<h1 style="margin:0 0 14px;color:#0f1722;font-size:20px;font-weight:700;line-height:1.3">${subject}</h1>
            <table width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#1c2434;border-collapse:collapse">
              <tr><th style="text-align:left;padding:6px 10px;color:#94a3b8;font-size:11px;letter-spacing:.4px">${en ? 'REP' : 'VENDEUR'}</th><th style="text-align:right;padding:6px 10px;color:#94a3b8;font-size:11px;letter-spacing:.4px">${en ? 'AMOUNT' : 'MONTANT'}</th></tr>
              ${rowsHtml}
              <tr><td style="padding:10px;border-top:2px solid #0f1722;font-weight:700">${en ? 'TOTAL' : 'TOTAL'}</td><td style="padding:10px;border-top:2px solid #0f1722;text-align:right;font-weight:700;color:#f97316">${money(grand)}</td></tr>
            </table>
            <p style="margin:18px 0 0;color:#94a3b8;font-size:11px">${en
              ? 'One-time bi-annual bonus tied to Zentact merchant processing volume — SEPARATE from regular monthly commissions. Detailed statement attached (PDF).'
              : 'Bonus bi-annuel unique lié au volume de traitement des marchands Zentact — DISTINCT des commissions mensuelles régulières. Relevé détaillé en pièce jointe (PDF).'}</p>`;
    const html = mailChrome(inner, subject);
    const pdf = await buildProcessingBonusPdf(periodLabel, reps, req.body.lang);
    const t = getMailer();
    if (!t) return res.status(502).json({ error: 'smtp_not_configured' });
    await t.sendMail({
      from: process.env.SMTP_FROM || process.env.SMTP_USER,
      to: recipients.join(','),
      subject,
      html,
      attachments: [{ filename: `Bonus_BiAnnuel_${periodLabel}.pdf`, content: pdf }],
    });
    const sentBy = req.user.realAdminEmail || req.user.email || 'unknown';
    const sentTo = recipients.join(', ');
    const values = [], params = [];
    reps.forEach((r, i) => {
      const b = i * 5;
      values.push(`($${b + 1}, $${b + 2}::date, $${b + 3}, $${b + 4}, $${b + 5})`);
      params.push(r.rep, period, sentTo, sentBy, r.total);
    });
    await pool.query(
      `INSERT INTO processing_bonus_sends (rep_name, period, sent_to, sent_by, total) VALUES ${values.join(', ')}`,
      params
    );
    res.json({ sent: true, recipients: recipients.length, reps: reps.length, grandTotal: grand });
  } catch (e) {
    console.error('[bonus-send] echec de l envoi:', e.stack || e.message);
    res.status(500).json({ error: `Failed to send processing bonus: ${e.message}`, details: e.message });
  }
});

// GET /api/commissions/processing-bonus/sends — history of bi-annual bonus send batches, its
// own history distinct from GET /api/commissions/payroll/sends.
app.get('/api/commissions/processing-bonus/sends', authenticateToken, async (req, res) => {
  if (!(await requirePerm(req, res, 'report:mark_paid'))) return;
  try {
    const rows = (await pool.query(`
      SELECT period::date AS period, sent_at, sent_by, sent_to,
             COUNT(*)::int AS rep_count,
             COALESCE(SUM(total), 0)::float AS total,
             ARRAY_AGG(rep_name ORDER BY rep_name) AS reps,
             ARRAY_AGG(id) AS ids
        FROM processing_bonus_sends
       GROUP BY period, sent_at, sent_by, sent_to
       ORDER BY sent_at DESC
       LIMIT 200
    `)).rows;
    const sends = rows.map(r => ({
      period: r.period, year: new Date(r.period).getUTCFullYear(), month: new Date(r.period).getUTCMonth() + 1,
      sentAt: r.sent_at, sentBy: r.sent_by,
      recipients: (r.sent_to || '').split(',').map(s => s.trim()).filter(Boolean),
      repCount: r.rep_count, total: r.total, reps: r.reps || [], ids: r.ids || [],
    }));
    res.json({ sends });
  } catch (e) {
    res.status(500).json({ error: 'Failed to load processing bonus send history', details: e.message });
  }
});

